'use strict';
const models=[['CB 300F TWISTER 2027','Street'],['BIZ KUROMI 2027','Urbanas'],['GL1800 GOLD WING TOUR 2026','Touring'],['X-ADV 2026','Adventure'],['XR300L TORNADO 2027','Trail'],['XRE 300 SAHARA 2027','Trail'],['TRX 420FM (4X4) 2026','Quadriciclo'],['BIZ 125 2027','Urbanas'],['CB500 HORNET 2026','Street'],['NX500 2026','Adventure'],['POP110i ES 2027','Urbanas'],['ELITE 125 2026','Scooter']].map(([name,category])=>({name,category,image:'assets/'+encodeURIComponent(name)+'-1200.webp',srcset:[480,800,1200].map(w=>'assets/'+encodeURIComponent(name)+'-'+w+'.webp '+w+'w').join(', ')}));
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let category='Todas',flow=null,step=0,data={},trigger=null;
const dialog=$('#flow-dialog'),body=$('#flow-body');
const generalMessage='Olá, Thiago! Vim pela sua página e gostaria de conhecer as motos disponíveis.';
document.querySelectorAll('.whatsapp').forEach(a=>a.href='https://wa.me/5591985910397?text='+encodeURIComponent(generalMessage));
$('#menu-button').onclick=()=>{const open=$('#navigation').classList.toggle('open');$('#menu-button').setAttribute('aria-expanded',open)};
$('#navigation').addEventListener('click',e=>{if(e.target.closest('a')){$('#navigation').classList.remove('open');$('#menu-button').setAttribute('aria-expanded','false')}});
const categories=['Todas',...new Set(models.map(m=>m.category))];
$('#filters').innerHTML=categories.map(c=>`<button aria-pressed="${c===category}" data-category="${c}">${c}</button>`).join('');
$('#filters').onclick=e=>{const b=e.target.closest('[data-category]');if(!b)return;category=b.dataset.category;$('#filters').querySelectorAll('button').forEach(x=>x.setAttribute('aria-pressed',x===b));catalog()};
$('#search').oninput=catalog;
function catalog(){const term=$('#search').value.toLocaleLowerCase('pt-BR').trim();const filtered=models.filter(m=>(category==='Todas'||m.category===category)&&m.name.toLowerCase().includes(term));$('#catalog-count').textContent=filtered.length+' modelos no catálogo';$('#catalog').innerHTML=filtered.length?filtered.map(m=>`<article class="moto-card"><div class="moto-photo"><img src="${m.image}" srcset="${m.srcset}" sizes="(max-width: 760px) 88vw, (max-width: 1050px) 43vw, 27vw" width="1200" height="725" loading="lazy" decoding="async" alt="${m.name}"></div><p class="moto-meta">${m.category.toUpperCase()} / ${m.name.slice(-4)}</p><h3>${m.name.slice(0,-5)}</h3><div class="card-actions"><button class="text-link" data-detail="${m.name}" aria-label="Ver detalhes de ${m.name}">Ver detalhes</button><button class="button primary" data-interest="${m.name}" aria-label="Tenho interesse em ${m.name}">TENHO INTERESSE ↗</button></div></article>`).join(''):'<p class="empty">Nenhum modelo encontrado. Experimente outro nome ou filtro.</p>'}
catalog();
function openDialog(){trigger=document.activeElement;dialog.showModal();document.body.classList.add('modal-open')}
function reset(){flow=null;step=0;data={};body.replaceChildren();document.body.classList.remove('modal-open');trigger?.focus()}
dialog.addEventListener('close',reset);$('#close-flow').onclick=()=>dialog.close();
document.addEventListener('click',e=>{const b=e.target.closest('[data-flow],[data-interest],[data-detail],.privacy-open');if(!b)return;if(b.matches('.privacy-open')){$('#privacy-dialog').showModal();return}if(b.dataset.flow){start(b.dataset.flow,data.moto||'');return}const name=b.dataset.interest||b.dataset.detail;data={moto:name};flow=null;$('#flow-kind').textContent='SUA PRÓXIMA HONDA';const m=models.find(x=>x.name===name);body.innerHTML=`<h2 id="flow-title" tabindex="-1">${b.dataset.detail?esc(name):'Como você quer conquistar sua Honda?'}</h2><img class="detail-image" src="${m.image}" srcset="${m.srcset}" sizes="(max-width:760px) 90vw, 600px" alt="${esc(name)}"><p><strong>${esc(name)}</strong> · ${m.category}</p><p>Consulte Thiago sobre versão, cores, disponibilidade e condições. Escolha como deseja seguir.</p><div class="choice-buttons"><button class="button primary" data-flow="financiamento">QUERO MEU FINANCIAMENTO ↗</button><button class="button outline" data-flow="consorcio">QUERO MEU CONSÓRCIO ↗</button></div>`;openDialog()});
document.querySelectorAll('.close-privacy').forEach(b=>b.onclick=()=>$('#privacy-dialog').close());
const personal=[['nome','Nome completo','text'],['cpf','CPF','cpf'],['nascimento','Data de nascimento','datebr'],['telefone','WhatsApp com DDD','phone'],['cnh','Possui CNH?','select',['Sim','Não']]];
function groups(){const p=[...personal];if(flow==='financiamento')p.splice(2,0,['rg','RG','text']);return flow==='financiamento'?[
{title:'Primeiro, vamos conhecer você.',short:'Dados pessoais',fields:p},
{title:'Qual é o seu próximo destino?',short:'Moto e proposta',fields:[['moto','Motocicleta desejada','moto'],['entrada','Quanto pretende dar de entrada?','money']]},
{title:'Onde você mora?',short:'Endereço',fields:[['cep','CEP da residência','cep'],['endereco','Endereço (rua, avenida…)','text'],['numero','Número (ou S/N)','text'],['complemento','Complemento (opcional)','optional']]},
{title:'Vamos entender sua renda.',short:'Renda',fields:[['tipoRenda','Tipo de renda','select',['CLT','Autônomo']],...(data.tipoRenda==='Autônomo'?[['profissao','Profissão / atividade','text']]:[]),['renda',data.tipoRenda==='Autônomo'?'Renda média mensal':'Renda mensal','positiveMoney']]},
{title:'Seus documentos, na conversa.',short:'Documentos',fields:[['comprovante','Comprovante de renda','select',['Tenho e enviarei pelo WhatsApp','Pendente — preciso de orientação']]]},
{title:'Confira suas informações.',short:'Revisão',fields:[]}]:[
{title:'Primeiro, vamos conhecer você.',short:'Dados pessoais',fields:p},
{title:'Qual Honda você quer?',short:'Moto',fields:[['moto','Motocicleta desejada','moto']]},
{title:'Como você está se planejando?',short:'Planejamento',fields:[['investimento','Quanto pretende investir?','positiveMoney'],['parcela','Parcela mensal que gostaria de considerar','positiveMoney'],['lance','Pretende oferecer lance?','select',['Sim','Não','Ainda não sei']],...(data.lance==='Sim'?[['valorLance','Valor aproximado do lance','positiveMoney']]:[])]},
{title:'Qual é o seu momento?',short:'Prazo e observações',fields:[['prazo','Quando pretende comprar?','select',['O quanto antes','Nos próximos meses','Ainda estou pesquisando']],['observacoes','Observações (opcional)','textarea']]},
{title:'Confira suas informações.',short:'Revisão',fields:[]}];}
function start(kind,moto=''){const wasOpen=dialog.open;flow=kind;step=0;data={moto:moto||'Ainda quero orientação'};$('#flow-kind').textContent=kind==='financiamento'?'SEU FINANCIAMENTO':'SEU CONSÓRCIO';render();if(!wasOpen)openDialog()}
function fieldHTML([id,label,type,options]){let input;const v=esc(data[id]||'');if(type==='select'||type==='moto'){const opts=type==='moto'?['Ainda quero orientação',...models.map(m=>m.name)]:options;input=`<select id="${id}" name="${id}" aria-describedby="error-${id}"><option value="">Selecione</option>${opts.map(o=>`<option ${data[id]===o?'selected':''}>${esc(o)}</option>`).join('')}</select>`}else if(type==='textarea')input=`<textarea id="${id}" name="${id}" rows="3" maxlength="600" aria-describedby="error-${id}">${v}</textarea>`;else{const numeric=['cpf','phone','cep','datebr','money','positiveMoney'].includes(type);const placeholder={cpf:'000.000.000-00',phone:'(91) 99999-9999',cep:'00000-000',datebr:'DD/MM/AAAA',money:'R$ 0,00',positiveMoney:'R$ 0,00'}[type]||'';const max={cpf:14,phone:15,cep:9,datebr:10,money:18,positiveMoney:18}[type]||100;input=`<input id="${id}" name="${id}" value="${v}" inputmode="${numeric?'numeric':'text'}" autocomplete="off" maxlength="${max}" placeholder="${placeholder}" aria-describedby="error-${id}">`}return `<label class="field ${['nome','endereco','moto','comprovante','observacoes'].includes(id)?'full':''}" for="${id}">${label}${input}<span class="error" id="error-${id}"></span></label>`}
function render(){const all=groups(),g=all[step],last=step===all.length-1;body.innerHTML=`<p class="progress-info" aria-live="polite">Etapa ${step+1} de ${all.length} · ${g.short}</p><progress max="${all.length}" value="${step+1}" aria-label="Progresso do formulário"></progress><h2 id="flow-title" tabindex="-1">${g.title}</h2>${step===0?'<p class="muted">Preencha para preparar seu atendimento. Você revisa tudo antes de abrir o WhatsApp.</p>':''}<form id="step-form" novalidate>${last?review():`<div class="fields">${g.fields.map(fieldHTML).join('')}</div>`}${g.short==='Documentos'?`<div class="hint"><strong>Nenhum arquivo é recebido nesta página.</strong><br>${data.tipoRenda==='CLT'?'Separe seu comprovante de renda ou holerite.':'Informe sua atividade e renda média. Comprovantes de movimentação ou renda poderão ser solicitados pela financeira.'}<br>Envie os documentos diretamente na conversa com Thiago, quando solicitado.</div>`:''}${g.short==='Planejamento'?'<p class="hint">Esses valores representam seu planejamento, não uma oferta ou parcela aprovada.</p>':''}${last?'<p class="hint">Ao continuar, os dados acima serão incluídos no link do WhatsApp, inclusive CPF, RG e renda quando preenchidos. Revise antes de abrir. A mensagem só é enviada quando você tocar em enviar no WhatsApp.</p><label class="consent"><input id="consent" type="checkbox">Confirmo as informações e autorizo o compartilhamento com Thiago pelo WhatsApp para atendimento desta solicitação.</label><p id="consent-error" class="error" role="alert"></p><button type="button" class="text-link privacy-open">Ler privacidade e uso de dados</button>':''}<div class="step-actions"><button type="button" class="button outline" id="back">${step?'VOLTAR':'CANCELAR'}</button><button type="submit" class="button primary">${last?'CONTINUAR NO WHATSAPP ↗':'CONTINUAR →'}</button></div><p id="flow-status" class="check-status" aria-live="polite"></p></form>`;
$('#back').onclick=()=>{if(step){step--;render()}else dialog.close()};$('#step-form').onsubmit=e=>{e.preventDefault();if(last){if(!$('#consent').checked){$('#consent-error').textContent='Autorize o compartilhamento para continuar.';$('#consent').focus();return}const message=buildMessage();window.open('https://wa.me/5591985910397?text='+encodeURIComponent(message),'_blank','noopener,noreferrer');$('#flow-status').textContent='Abertura do WhatsApp solicitada. Confira a conversa e toque em enviar para concluir. Se não abriu, permita a nova aba e tente novamente.';return}if(validate()){step++;render()}};
g.fields.forEach(f=>{const el=document.getElementById(f[0]);el.addEventListener('input',()=>{if(['cpf','phone','cep','datebr','money','positiveMoney'].includes(f[2]))el.value=mask(el.value,f[2]);data[f[0]]=el.value;el.removeAttribute('aria-invalid');$('#error-'+f[0]).textContent=''});el.addEventListener('blur',()=>validateField(f));if(['tipoRenda','lance'].includes(f[0]))el.addEventListener('change',()=>{data[f[0]]=el.value;if(f[0]==='tipoRenda'&&el.value!=='Autônomo')delete data.profissao;if(f[0]==='lance'&&el.value!=='Sim')delete data.valorLance;render();document.getElementById(f[0]).focus()})});body.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{step=Number(b.dataset.edit);render()});if(dialog.open)$('#flow-title').focus();dialog.scrollTop=0;}
function mask(value,type){let n=value.replace(/\D/g,'');if(type==='cpf')return n.slice(0,11).replace(/^(\d{3})(\d)/,'$1.$2').replace(/^(\d{3})\.(\d{3})(\d)/,'$1.$2.$3').replace(/(\d{3})\.(\d{3})\.(\d{3})(\d)/,'$1.$2.$3-$4');if(type==='cep')return n.slice(0,8).replace(/(\d{5})(\d)/,'$1-$2');if(type==='datebr')return n.slice(0,8).replace(/(\d{2})(\d)/,'$1/$2').replace(/(\d{2})\/(\d{2})(\d)/,'$1/$2/$3');if(type==='phone'){n=n.slice(0,11);return n.replace(/^(\d{2})(\d)/,'($1) $2').replace(/(\d{5})(\d{1,4})$/,'$1-$2')}return n?new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(Number(n.slice(0,11))/100):''}
function validCPF(v){const n=v.replace(/\D/g,'');if(n.length!==11||/^(\d)\1+$/.test(n))return false;for(let size=9;size<=10;size++){let s=0;for(let i=0;i<size;i++)s+=Number(n[i])*(size+1-i);const digit=(s*10)%11;if((digit===10?0:digit)!==Number(n[size]))return false}return true}
function validation(f){const[id,,type]=f,v=(data[id]||'').trim(),n=v.replace(/\D/g,'');if(['optional','textarea'].includes(type))return '';if(!v)return 'Preencha este campo para continuar.';if(id==='nome'&&(v.split(/\s+/).length<2||v.length<5))return 'Informe seu nome completo.';if(type==='cpf'&&!validCPF(v))return 'Confira os 11 dígitos do CPF.';if(id==='rg'&&(v.length<4||!/[0-9]/.test(v)))return 'Confira o número do RG.';if(type==='phone'&&!/^[1-9]{2}9\d{8}$/.test(n))return 'Informe DDD e celular com 9 dígitos.';if(type==='cep'&&n.length!==8)return 'Informe os 8 dígitos do CEP.';if(type==='datebr'){const [d,m,y]=v.split('/').map(Number),date=new Date(y,m-1,d);if(!/^\d{2}\/\d{2}\/\d{4}$/.test(v)||y<1900||date.getFullYear()!==y||date.getMonth()!==m-1||date.getDate()!==d||date>=new Date())return 'Informe uma data de nascimento válida.'}if(type==='positiveMoney'&&Number(n)<=0)return 'Informe um valor maior que zero.';return ''}
function validateField(f){const error=validation(f),el=document.getElementById(f[0]);$('#error-'+f[0]).textContent=error;el.setAttribute('aria-invalid',String(Boolean(error)));return !error}
function validate(){const results=groups()[step].fields.map(validateField);if(results.includes(false)){body.querySelector('[aria-invalid=true]')?.focus();return false}return true}
function review(){return groups().slice(0,-1).map((g,i)=>`<section class="review-group"><div class="review-header"><h3>${g.short}</h3><button type="button" class="text-link" data-edit="${i}" aria-label="Editar ${g.short}">Editar</button></div><dl>${g.fields.map(([id,label])=>`<dt>${esc(label)}</dt><dd>${esc(data[id]||'Não informado')}</dd>`).join('')}</dl></section>`).join('')}
function buildMessage(){return 'Olá, Thiago! Vim pela sua página e tenho interesse em '+(flow==='financiamento'?'financiamento':'consórcio')+'.\n\n'+groups().slice(0,-1).map(g=>g.short.toUpperCase()+'\n'+g.fields.map(([id,label])=>label+': '+(data[id]||'Não informado')).join('\n')).join('\n\n')+'\n\nDocumentos: nenhum arquivo anexado nesta página.\nGostaria de receber orientação sobre as próximas etapas.\nAutorizei o contato referente a esta solicitação.'}
window.addEventListener('pagehide',()=>{data={};if(dialog.open)dialog.close()});

